import ast
_uses = {}
for _n in ast.walk(ast.parse(__source__)):
    if isinstance(_n, (ast.Assign, ast.AugAssign, ast.AnnAssign)) and _n.value is not None:
        _names = {v.id for v in ast.walk(_n.value) if isinstance(v, ast.Name)}
        _deps = set(_names).union(*(_uses.get(v, set()) for v in _names))
        for _x in (_n.targets if isinstance(_n, ast.Assign) else [_n.target]):
            if isinstance(_x, ast.Name):
                _uses[_x.id] = _deps | ({_x.id} | _uses.get(_x.id, set()) if isinstance(_n, ast.AugAssign) else set())
assert {'price', 'count'} <= _uses.get('subtotal', set()), 'compute subtotal from price and count'
assert 'subtotal' in _uses.get('tax', set()), 'compute tax from subtotal'
assert _uses.get('total', set()) & {'subtotal', 'tax'}, 'compute total from subtotal and tax'
